def run_cells(cells):
    In, Out = [""], {}
    for n, src in enumerate(cells, start=1):
        In.append(src)
        text = src.rstrip()
        quiet = text.endswith(";")
        value = eval(text.rstrip(";"))
        if value is not None and not quiet:
            Out[n] = value
    return In, Out

