import traceback

def unit_cost(total, units):
    return total / units

def report(rows):
    out = []
    for t, u in rows:
        out.append(unit_cost(t, u))
    return out

try:
    report([(100, 4), (50, 0)])
except ZeroDivisionError as e:
    frames = traceback.extract_tb(e.__traceback__)
    print([f.name for f in frames])

