RATES = {"north": 0.03, "south": 0.025}

def lookup_rate(region):
    return RATES[region]

def project(region, base):
    return base * (1 + lookup_rate(region))

def run_model():
    out = []
    for r in ["north", "west"]:
        out.append(project(r, 100))
    return out

