import cProfile, pstats

def tax(income):
    return 0.2 * income

def payroll(n):
    return sum(tax(w) for w in range(n))

prof = cProfile.Profile()
prof.enable()
payroll(25)
prof.disable()

stats = pstats.Stats(prof).stats
for (filename, line, func), (cc, ncalls, tt, ct, callers) in stats.items():
    if func == "tax":
        print(ncalls)

