def draw_shock(t):
    return ((t * 7919) % 101) / 100 - 0.5

def simulate(n):
    path = [0.0]
    for t in range(n):
        for k in range(3):
            path.append(path[-1] * 0.9 + draw_shock(t + k))
    return path
